import { supabase } from './client'
import type { Objective } from '@/entities/objective/types'

export const objectivesService = {
  async listObjectives(projectId: string): Promise<Objective[]> {
    const { data, error } = await supabase
      .from('objectives')
      .select('*')
      .eq('project_id', projectId)
      .order('created_at', { ascending: false })
    if (error) throw error
    return (data ?? []) as Objective[]
  },

  async getObjective(objectiveId: string): Promise<Objective | null> {
    const { data, error } = await supabase.from('objectives').select('*').eq('id', objectiveId).single()
    if (error) return null
    return data as Objective
  },

  async createObjective(objective: Omit<Objective, 'id' | 'createdAt' | 'updatedAt'>): Promise<Objective> {
    const { data, error } = await supabase.from('objectives').insert(objective).select().single()
    if (error) throw error
    return data as Objective
  },

  async updateObjective(objectiveId: string, updates: Partial<Objective>): Promise<void> {
    const { error } = await supabase.from('objectives').update(updates).eq('id', objectiveId)
    if (error) throw error
  },
}
